// context-cache: a panel above the prompt with context usage, usage limits
// (session, weekly, Fable) and prompt-cache temperature, plus Clear / Compact / Warm.
//
// Where each number comes from (all real, nothing sampled):
// - Context: $.session.usage() (the status line's figures) and its /context
//   breakdown; Files is the share of Messages that is file contents read.
// - Limits: the account usage endpoint (api.anthropic.com/api/oauth/usage),
//   called with the session's own credential through the host; falls back to
//   the rate-limit headers of the last response, then to the last good
//   account reading any session saved (windows that have reset are dropped).
// - Cache: the time of the last main-thread response, the TTL the responses
//   were cached with (read from the transcript's usage, or the engine's own
//   model-switch report), and the last turn's cache-read share.
// - Prices: $.session.model(), priced from the list in model.ts. After a Clear
//   or Compact the notice says what was taken out (context before and after).
//
// Also: auto-warm above a context size (/cache-autowarm), a notice when the
// cache has 5 minutes left, a toast as a limit reaches 90%, a pulse when a bar
// turns amber or red, and the band as one line (/cache-mini).

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { ContextCacheCache, ContextCacheLimit, ContextCacheSnapshot, ContextCacheWarming } from '../types'
import {
  buildContext,
  buildView,
  cacheView,
  fmtClock,
  fmtSpan,
  fmtTokens,
  fmtUsd,
  priceOf,
  noticeText,
  pct,
  sizeClassOf,
  type ViewModel,
  fileShareOf,
  isPulseLit,
  limitToast,
  miniLine,
  limitsFromResponse,
  listPrice,
  parseAccountUsage,
  timePct,
  toneOf,
  TTL_1H,
  TTL_5M,
  usageWindowsOf,
  warmNotice,
} from './model'
import { renderDesktop, renderMini, renderTerminal, type Actions } from './view'

const snapshotAtom = atom({ plugin: 'context-cache', key: 'snapshot' } as const, null)
const hiddenAtom = atom({ plugin: 'context-cache', key: 'isHidden' } as const, false)
const nowAtom = atom({ plugin: 'context-cache', key: 'now' } as const, 0)
// Desktop and mobile draw the design in CSS px, but the band is measured in
// cells; this is the conversion. 8 fits the desktop app's default font;
// /cache scale <px> adjusts it and the value is kept across sessions.
const pxPerCellAtom = atom({ plugin: 'context-cache', key: 'pxPerCell' } as const, 8)
const DEFAULT_PX_PER_CELL = 8
const warmUntilAtom = atom({ plugin: 'context-cache', key: 'warmUntil' } as const, null)
// /cache-mini: the band as one line; kept across sessions in the store.
const miniAtom = atom({ plugin: 'context-cache', key: 'isMini' } as const, false)

// Keep-warm: a cache read resets the 1h TTL for free, so one tool-less fork of
// the main thread 55 min after the last reply keeps it alive at the cache-read
// price (a tenth of input on most models, a twentieth on Opus 5.5) where a
// cold re-write is 2x input. The fork never enters the transcript.
const WARM_AFTER_MS = 55 * 60_000
const WARM_FOR_MS = 8 * 60 * 60_000
const WARM_PROMPT = 'Keep-alive ping for the prompt cache. Reply with only: ok'
let warmInFlight = false
/** The last successful ping of this warming run, for the notice line. */
let lastPing: { at: number; read: number } | null = null
/** This warming run for /cache-status, kept in the store so a reload keeps it. */
type WarmRun = { startedAt: number; until: number; pings: { at: number; read: number }[] }

async function startWarmRun($: EngineInterface, startedAt: number, until: number) {
  lastPing = null
  await $.store.set('warmRun', { startedAt, until, pings: [] } satisfies WarmRun)
}

const USAGE_URL = 'https://api.anthropic.com/api/oauth/usage'
// The account endpoint answers 429 to anyone who leans on it; the status-line
// tools that use it hold to one request per 5 minutes, so this does too. The
// 5h/7d figures still move every response through the rate-limit headers.
const ACCOUNT_EVERY_MS = 5 * 60_000
// Two reset times this close describe the same window (the sources round differently).
const SAME_WINDOW_MS = 30 * 60_000
const MAX_TRANSCRIPT_BYTES = 4 * 1024 * 1024 - 1024

const emptyCache = (ttlMs: number, isTtlKnown: boolean): ContextCacheCache => ({
  lastAt: null,
  ttlMs,
  isTtlKnown,
  hitRate: null,
})

/** The TTL a response was cached with, from a transcript line's usage. */
export function ttlFromTranscript(text: string): number | null {
  const lines = text.split('\n')
  for (let i = lines.length - 1, seen = 0; i >= 0 && seen < 400; i--, seen++) {
    const line = lines[i]
    if (!line || !line.includes('cache_creation')) continue
    try {
      const row = JSON.parse(line) as { message?: { usage?: { cache_creation?: Record<string, number> } } }
      const cc = row.message?.usage?.cache_creation
      if (!cc) continue
      if ((cc['ephemeral_1h_input_tokens'] ?? 0) > 0) return TTL_1H
      if ((cc['ephemeral_5m_input_tokens'] ?? 0) > 0) return TTL_5M
    } catch {
      // a partial line; keep looking
    }
  }
  return null
}

// Module state: rebuilt on reload; what the drawing needs lives in $.state.
let accountLimits: ContextCacheLimit[] | null = null
let accountAt = 0
let accountInFlight = false
let refreshing: Promise<void> | null = null
// Diagnostics for /cache status: what asked the mod to draw, and where, and
// how the last account usage request went.
const draws: Record<string, number> = {}
const attached: string[] = []
let cwd = ''
const DIAG_FILE = 'context-cache-status.json' // written in the session's working directory
type AccountDiag = {
  at: number
  authKind: string
  status: number | null
  ok: boolean | null
  topLevelKeys: string[]
  /** JSON paths of every node with a utilization figure, and which matched Fable. */
  windows: string[]
  fableMatched: string[]
  bodyPreview: string
  error: string | null
}
let lastAccount: AccountDiag | null = null

function noteDraw(component: string, surface: string) {
  const k = `${component}@${surface}`
  draws[k] = (draws[k] ?? 0) + 1
}

async function statusReport($: EngineInterface): Promise<string> {
  let surfaces: readonly string[] = []
  try {
    surfaces = await $.session.surfaces()
  } catch {
    surfaces = []
  }
  const [snap, hidden, pxPerCell, warmUntil] = await Promise.all([
    read($, snapshotAtom),
    read($, hiddenAtom),
    read($, pxPerCellAtom),
    read($, warmUntilAtom),
  ])
  const warming = snap ? await warmingOf($, snap) : null
  const drawn = Object.entries(draws).map(([k, n]) => `${k} ×${n}`).join(', ') || 'nothing yet'
  const a = lastAccount
  const account = a
    ? `auth ${a.authKind}, HTTP ${a.status ?? '—'}${a.ok === false ? ' (not ok)' : ''}` +
      `${a.error ? `, error: ${a.error}` : ''}; keys: ${a.topLevelKeys.join(', ') || '—'}; ` +
      `windows: ${a.windows.join(', ') || 'none'}; Fable matched: ${a.fableMatched.join(', ') || 'none'}`
    : 'not attempted yet'
  const lines = [
    `Surfaces attached now: ${surfaces.length ? surfaces.join(', ') : 'none'}`,
    `Clients that attached since load: ${attached.length ? attached.join(', ') : 'none seen'}`,
    `Draw requests received: ${drawn}`,
    `Panel hidden: ${hidden ? 'yes' : 'no'}; px per cell: ${pxPerCell} (/cache scale <px> changes it)`,
    `Context: ${snap?.context ? `${snap.context.used} / ${snap.context.window}` : 'no reading'}`,
    `Limits: ${snap?.limits.length ? snap.limits.map(l => `${l.kind} ${l.usage}%`).join(', ') : 'none'} (source: ${snap?.limitsSource ?? 'none'})`,
    `Account usage request: ${account}`,
    `Cache: last write ${snap?.cache.lastAt ? new Date(snap.cache.lastAt).toISOString() : 'none'}, TTL ${snap ? snap.cache.ttlMs / 60000 : '?'}m${snap?.cache.isTtlKnown ? '' : ' (default)'}`,
    priceLine(snap?.model),
    ...tallyLines(await readDays($)),
    `Warming: ${warmUntil === null ? 'off' : `on until ${fmtClock(warmUntil)}; ${warming ? warmNotice(warming, snap!.context)[0] : 'no note'}`}`,
    ...(warmUntil === null ? [] : warmRunLines((await $.store.get('warmRun')) as WarmRun | null | undefined, snap, warming, await $.clock.now())),
    `Auto-warm: ${(await autoWarmAt($)) === 0 ? 'off (/cache-autowarm sets it)' : `when quiet with a context over ${fmtTokens(await autoWarmAt($))}${autoHeld ? '; held off until the next reply' : ''}`}`,
    `Full report: ${cwd ? `${cwd}/` : ''}${DIAG_FILE}`,
  ]
  const text = lines.join('\n')
  try {
    await $.fs.write(
      DIAG_FILE,
      JSON.stringify({ at: await $.clock.now(), surfaces, attached, draws, hidden, pxPerCell, account: lastAccount, snap }, null, 2),
    )
  } catch {
    // diagnostics only
  }
  return text
}

async function current($: EngineInterface): Promise<ContextCacheSnapshot> {
  const snap = await read($, snapshotAtom)
  if (snap) return snap
  const stored = await $.store.get('ttlMs')
  const ttl = stored === TTL_5M || stored === TTL_1H ? stored : TTL_1H
  return {
    context: null,
    limits: [],
    limitsSource: 'none',
    cache: emptyCache(ttl, stored === TTL_5M || stored === TTL_1H),
    updatedAt: await $.clock.now(),
  }
}

async function patchCache($: EngineInterface, patch: Partial<ContextCacheCache>) {
  const base = await current($)
  await update($, snapshotAtom, prev => {
    const s = prev ?? base
    return { ...s, cache: { ...s.cache, ...patch } }
  })
}

async function setTtl($: EngineInterface, ttlMs: number) {
  await $.store.set('ttlMs', ttlMs)
  await patchCache($, { ttlMs, isTtlKnown: true })
}

/** The last account reading any session saved, when it is newer than this session's own. */
async function adoptShared($: EngineInterface) {
  const saved = (await $.store.get('accountLimits')) as { at?: number; limits?: ContextCacheLimit[] } | undefined
  if (saved?.limits?.length && typeof saved.at === 'number' && saved.at > accountAt) {
    accountLimits = saved.limits
    accountAt = saved.at
  }
}

// Every open session shares one request: whoever asks first writes the time to
// the store, and the others take the reading it saves instead of asking too.
// ponytail: two sessions reading the claim in the same instant both ask; rare, and a 429 backs both off.
async function fetchAccount($: EngineInterface, now: number, force: boolean) {
  if (accountInFlight) return
  if (!force) {
    const asked = await $.store.get('accountAskedAt')
    if (typeof asked === 'number' && now - asked < ACCOUNT_EVERY_MS) return adoptShared($)
  }
  await $.store.set('accountAskedAt', now)
  accountInFlight = true
  const diag: AccountDiag = { at: now, authKind: 'none', status: null, ok: null, topLevelKeys: [], windows: [], fableMatched: [], bodyPreview: '', error: null }
  lastAccount = diag
  try {
    const auth = await $.session.authorize()
    diag.authKind = auth ? auth.kind : 'none'
    if (!auth || auth.kind !== 'bearer') return
    const res = await $.http.fetch(USAGE_URL, {
      auth: auth.handle,
      headers: { 'anthropic-beta': 'oauth-2025-04-20', accept: 'application/json' },
    })
    diag.status = res.status
    diag.ok = res.ok
    diag.bodyPreview = res.text.slice(0, 2000)
    if (res.status === 429) {
      // Back off a whole interval (or what retry-after asks) before trying again.
      // The claim moves on so that no session asks before then.
      const retry = Number(res.headers['retry-after'])
      await $.store.set('accountAskedAt', now + (Number.isFinite(retry) && retry > 0 ? Math.max(0, retry * 1000 - ACCOUNT_EVERY_MS) : 0))
      return
    }
    if (!res.ok) return
    const json: unknown = JSON.parse(res.text)
    if (json && typeof json === 'object') diag.topLevelKeys = Object.keys(json as object)
    const found = usageWindowsOf(json)
    diag.windows = found.map(f => `${f.path}=${f.usage}%`)
    diag.fableMatched = found.filter(f => f.isFable).map(f => f.path)
    const limits = parseAccountUsage(json)
    if (limits.length > 0) {
      accountLimits = limits
      accountAt = now
      await $.store.set('accountLimits', { at: now, limits })
    }
  } catch (err) {
    // keep the last good reading; the response headers cover the gap
    diag.error = err instanceof Error ? err.message : String(err)
  } finally {
    accountInFlight = false
  }
}

// The Files share of the conversation: reading the whole transcript is the
// dear part of a refresh, so it is done once per turn and reused between.
let fileShare = 0
let fileShareTurn = -1
let turnNo = 0

async function doRefresh($: EngineInterface, forceAccount: boolean) {
  const now = await $.clock.now()
  const prev = await current($)

  let context = prev.context
  let responseLimits: ContextCacheLimit[] = []
  try {
    const usage = await $.session.usage({ breakdown: 'summary' })
    responseLimits = limitsFromResponse(usage.rateLimits)
    const b = usage.context.breakdown
    if (fileShareTurn !== turnNo) {
      try {
        const msgs = await $.session.messages()
        if (Array.isArray(msgs)) fileShare = fileShareOf(msgs)
        fileShareTurn = turnNo
      } catch {
        // keep the last share
      }
    }
    context = buildContext({
      categories: b?.categories ?? [],
      realTokens: usage.context.tokens ?? b?.totalTokens,
      window: usage.context.window,
      autoCompactAt: b?.autoCompactThreshold,
      isAutoCompactEnabled: b?.isAutoCompactEnabled ?? false,
      fileShare,
    })
  } catch {
    // keep the last context reading
  }

  await fetchAccount($, now, forceAccount)
  // A reload empties module memory but not the session's snapshot: a recent
  // account reading there still stands, so Fable does not blink out meanwhile.
  if (accountLimits === null && prev.limitsSource === 'account' && now - prev.updatedAt < 10 * ACCOUNT_EVERY_MS) {
    accountLimits = prev.limits
    accountAt = prev.updatedAt
  }
  const isAccountFresh = accountLimits !== null && now - accountAt < 10 * ACCOUNT_EVERY_MS
  let limits: ContextCacheLimit[]
  let limitsSource: ContextCacheSnapshot['limitsSource']
  if (isAccountFresh && accountLimits) {
    // The headers arrive with every reply and the account reading is up to 5
    // minutes old, yet the headers can trail it (weekly 25% against the
    // account's and /usage's 26%). Usage only climbs inside a window, so for
    // the same window the higher reading is the newer one; across a reset the
    // later window wins. The account adds what the headers lack (Fable).
    limits = [
      ...responseLimits.map(r => {
        const a = accountLimits!.find(x => x.kind === r.kind)
        if (!a) return r
        const resetsAt = r.resetsAt ?? a.resetsAt
        if (resetsAt !== null && a.resetsAt !== null && Math.abs(resetsAt - a.resetsAt) > SAME_WINDOW_MS) {
          return a.resetsAt > resetsAt ? a : { ...r, resetsAt }
        }
        return { ...r, resetsAt, usage: Math.max(r.usage, a.usage) }
      }),
      ...accountLimits.filter(a => !responseLimits.some(r => r.kind === a.kind)),
    ]
    limitsSource = 'account'
  } else if (responseLimits.length > 0) {
    limits = responseLimits
    limitsSource = 'response'
  } else if (prev.limits.length > 0) {
    limits = prev.limits
    limitsSource = prev.limitsSource
  } else {
    // Nothing read in this session yet (a reopened old chat before its first
    // reply): the last good account reading from any session, minus windows
    // that have reset since. It is replaced by the next real reading.
    const saved = (await $.store.get('accountLimits')) as { limits?: ContextCacheLimit[] } | undefined
    limits = (saved?.limits ?? []).filter(l => l.resetsAt !== null && l.resetsAt > now)
    limitsSource = limits.length > 0 ? 'account' : 'none'
  }

  let model = prev.model ?? null
  try {
    model = await $.session.model()
  } catch {
    // keep the last one read; without it the notice leaves out prices
  }

  // A bar that just turned amber or red pulses; one already so when the session opened does not.
  const rank = { normal: 0, amber: 1, red: 2 } as const
  const toneAt = (l: ContextCacheLimit) => rank[toneOf(l.usage, timePct(l, now))]
  const pulse = { ...prev.pulse }
  for (const l of limits) {
    const was = prev.limits.find(p => p.kind === l.kind)
    if (was && toneAt(l) > toneAt(was)) pulse[l.kind] = now
  }
  await warnLimits($, limits, now)

  await update($, snapshotAtom, latest => {
    const s = latest ?? prev
    return { ...s, context, limits, limitsSource, model, pulse, updatedAt: now }
  })
  await update($, nowAtom, () => now)
}

/**
 * One toast as a limit reaches 90%, once per window across every session: the
 * windows already warned about are kept in the store until they reset.
 */
async function warnLimits($: EngineInterface, limits: ContextCacheLimit[], now: number) {
  const due = limits.filter(l => l.usage >= 90 && l.resetsAt !== null && l.resetsAt > now)
  if (due.length === 0) return
  const warned = (((await $.store.get('limitWarned')) as string[] | undefined) ?? []).map(k => {
    const [kind, at] = k.split('@')
    return { kind, at: Number(at) }
  })
  // The sources round reset times differently: within SAME_WINDOW_MS is the same window.
  const fresh = due.filter(l => !warned.some(w => w.kind === l.kind && Math.abs(w.at - l.resetsAt!) < SAME_WINDOW_MS))
  if (fresh.length === 0) return
  const keep = warned.filter(w => w.at > now).map(w => `${w.kind}@${w.at}`)
  await $.store.set('limitWarned', [...keep, ...fresh.map(l => `${l.kind}@${l.resetsAt}`)])
  for (const l of fresh) $.ui.toast(limitToast(l, now))
}

function refresh($: EngineInterface, forceAccount = false): Promise<void> {
  if (refreshing) return refreshing
  refreshing = doRefresh($, forceAccount)
    .catch(() => undefined) // a refresh outliving its session, or a refused write: the next one retries
    .finally(() => {
    refreshing = null
  })
  return refreshing
}

/** After a Clear or Compact: re-read the context and keep what was taken out, for the notice. */
async function noteSaved($: EngineInterface, kind: 'clear' | 'compact', before: number | null) {
  // A refresh already in flight read the context from before; the second reads it after.
  await refresh($)
  await refresh($)
  const after = (await current($)).context?.used ?? 0
  if (before === null || before <= after) return
  await update($, snapshotAtom, s => (s ? { ...s, saved: { kind, before, after } } : s))
  const snap = await current($)
  const price = priceOf(snap.model, snap.cache.ttlMs)
  await addToTally($, { freed: before - after, freedUsd: price ? (before - after) * price.write : 0 })
}

// What Clear, Compact and Warm saved, per local day for the last 7, kept
// across sessions for /cache-status. Money is the cache re-write each one
// spared, at list price.
type Totals = { freed: number; freedUsd: number; pings: number; pingUsd: number }
type Days = Record<string, Totals>
const NONE: Totals = { freed: 0, freedUsd: 0, pings: 0, pingUsd: 0 }
const DAY_MS = 24 * 60 * 60_000

/** "2026-10-13" in local time: keys that sort, unlike toDateString. */
const dayKey = (at: number) => {
  const d = new Date(at)
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}

/** The last 7 days' totals, today among them; older days dropped. */
async function readDays($: EngineInterface): Promise<{ today: string; days: Days }> {
  const now = await $.clock.now()
  const today = dayKey(now)
  const oldest = dayKey(now - 6 * DAY_MS)
  let days = ((await $.store.get('tallyDays')) as Days | undefined) ?? {}
  // Before 0.1.10 only today was kept, under 'tally'.
  const old = (await $.store.get('tally')) as (Totals & { day: string }) | undefined
  if (old && old.day === new Date(now).toDateString() && !days[today]) {
    const { day: _, ...t } = old
    days = { ...days, [today]: t }
  }
  return { today, days: Object.fromEntries(Object.entries(days).filter(([k]) => k >= oldest && k <= today)) }
}

async function addToTally($: EngineInterface, add: Partial<Totals>) {
  const { today, days } = await readDays($)
  const t = days[today] ?? NONE
  const sum = (k: keyof Totals) => t[k] + (add[k] ?? 0)
  await $.store.set('tallyDays', { ...days, [today]: { freed: sum('freed'), freedUsd: sum('freedUsd'), pings: sum('pings'), pingUsd: sum('pingUsd') } })
}

function tallyLines({ today, days }: { today: string; days: Days }): string[] {
  const t = days[today] ?? NONE
  const w = Object.values(days).reduce<Totals>(
    (a, d) => ({ freed: a.freed + d.freed, freedUsd: a.freedUsd + d.freedUsd, pings: a.pings + d.pings, pingUsd: a.pingUsd + d.pingUsd }),
    NONE,
  )
  const money = (usd: number) => (usd > 0 ? ` (up to ${fmtUsd(usd)} of cache re-writes)` : '')
  const pings = (n: number) => `${n} Warm ping${n === 1 ? '' : 's'}`
  const week =
    w.freed === 0 && w.pings === 0
      ? 'nothing yet'
      : [
          w.freed > 0 ? `${fmtTokens(w.freed)} taken out by Clear and Compact${w.freedUsd > 0 ? ` (up to ${fmtUsd(w.freedUsd)})` : ''}` : 'nothing taken out by Clear or Compact',
          w.pings > 0 ? `${pings(w.pings)}${w.pingUsd > 0 ? ` (${fmtUsd(w.pingUsd)} of re-writes avoided)` : ''}` : 'no Warm pings',
        ].join(', ')
  return [
    `Saved today by Clear and Compact: ${t.freed > 0 ? `${fmtTokens(t.freed)} taken out of the context${money(t.freedUsd)}` : 'nothing yet'}`,
    `Saved today by Warm: ${t.pings > 0 ? `${t.pings} ping${t.pings === 1 ? '' : 's'} kept the cache${t.pingUsd > 0 ? `, ${fmtUsd(t.pingUsd)} of re-writes avoided after paying for the pings` : ''}` : 'no pings yet'}`,
    `Saved in the last 7 days: ${week}`,
  ]
}

/** The current Warm run: when it started and ends, each ping, and what the pings spared (as addToTally counts it). */
function warmRunLines(run: WarmRun | null | undefined, snap: ContextCacheSnapshot | null, warming: ContextCacheWarming | null, now: number): string[] {
  if (!run) return []
  const last = run.pings.at(-1)
  const price = snap ? priceOf(snap.model, snap.cache.ttlMs) : null
  const lines = [
    `Warm run: on since ${fmtClock(run.startedAt)} (${fmtSpan(now - run.startedAt)}), ends ${fmtClock(run.until)} (${fmtSpan(run.until - now)} left)`,
    `Pings: ${run.pings.length ? run.pings.map(p => fmtClock(p.at).replace(/ [ap]m$/, '')).join(', ') : 'none yet'}` +
      `${warming ? ` · next ${fmtClock(warming.nextAt).replace(/ [ap]m$/, '')}` : ''}${last ? ` · ${fmtTokens(last.read)} kept cached each` : ''}`,
  ]
  // A ping is a fork: nothing enters the chat.
  if (price && last)
    lines.push(`Each ping: 0 tokens added to the chat · reads ${fmtTokens(last.read)} from cache · costs ${fmtUsd(last.read * price.read)} · saves ${fmtUsd(last.read * price.write)} (net ${fmtUsd(last.read * (price.write - price.read))})`)
  if (price && run.pings.length) {
    const read = run.pings.reduce((n, p) => n + p.read, 0)
    lines.push(`This run: ${fmtUsd(read * (price.write - price.read))} of re-writes avoided (pings ${fmtUsd((read * price.read) / run.pings.length)} each)`)
  }
  return lines
}

/** Which list prices the money comes from, or that the model has none. */
function priceLine(model: string | null | undefined): string {
  if (!model) return 'Prices: the model is not known yet, so the panel shows tokens without money'
  const p = listPrice(model)
  return p
    ? `Prices: ${model} at $${p.input} input, $${p.read} cache read per million tokens`
    : `Prices: ${model} is not in the price list in hooks/model.ts, so the panel shows tokens without money`
}

async function learnTtl($: EngineInterface, transcriptPath: string) {
  if (!transcriptPath) return
  try {
    const stat = await $.fs.stat(transcriptPath)
    if (stat.size > MAX_TRANSCRIPT_BYTES) return
    const text = await $.fs.read(transcriptPath)
    const ttl = ttlFromTranscript(typeof text === 'string' ? text : '')
    if (ttl !== null) await setTtl($, ttl)
  } catch {
    // unreadable: the stored TTL stands
  }
}

const PANE = 'context-cache'

const COMMANDS = [
  { name: 'cache', description: 'Context & cache panel: show or hide it' },
  { name: 'cache-status', description: 'Context & cache panel: where each figure comes from (surfaces, draws, the account usage request, Fable) and what was saved today' },
  { name: 'cache-mini', description: 'Context & cache panel: one line (context %, cache, the next message\'s price) or the whole card' },
  { name: 'cache-pane', description: 'Context & cache panel: open it as a pane (the way it shows on mobile)' },
  { name: 'cache-refresh', description: 'Context & cache panel: re-read usage now' },
  { name: 'cache-scale', description: 'Context & cache panel: px per cell the desktop draws at (default 8); a number sets it, none steps it', argumentHint: '[px]' },
  {
    name: 'cache-autowarm',
    description: 'Context & cache panel: switch Warm on by itself when you go quiet with a context over this many thousand tokens; 0 is off, none steps off/200/300/500',
    argumentHint: '[k tokens]',
  },
] as const

async function hasMobile($: EngineInterface): Promise<boolean> {
  try {
    return (await $.session.surfaces()).includes('mobile')
  } catch {
    return false
  }
}

/** The card's inner width in CSS px on a remote surface: the band's cells × px per cell, less the border. */
async function widthPx($: EngineInterface, columns: number): Promise<number> {
  return columns * (await read($, pxPerCellAtom)) - 2
}

/** The terminal notice's room: the card's border and padding, "● ", and beside the buttons ([Clear] [Compact] [Warm]) when wide. */
function terminalNoticeChars(columns: number): number {
  const wide = sizeClassOf(columns) === 'a' || sizeClassOf(columns) === 'b'
  return columns - 6 - (wide ? 25 : 0)
}

/** The size classes are set in the design's cells (8px each): a px width as that many. */
function designCells(px: number): number {
  return px / DEFAULT_PX_PER_CELL
}

/** The view model for a drawing, or null while hidden or before any reading. */
async function panelModel($: EngineInterface, columns: number, maxRows: number, fitChars?: number): Promise<ViewModel | null> {
  const [snap, hidden, tick] = await Promise.all([read($, snapshotAtom), read($, hiddenAtom), read($, nowAtom)])
  if (hidden || !snap) return null
  return buildView({ ...snap, warming: await warmingOf($, snap) }, Math.max(tick, snap.updatedAt), columns, maxRows, fitChars)
}

/** While warming: the last ping and when the next is due, for the notice line. */
async function warmingOf($: EngineInterface, { cache }: ContextCacheSnapshot): Promise<ContextCacheWarming | null> {
  if ((await read($, warmUntilAtom)) === null || cache.lastAt === null) return null
  return { lastPing, nextAt: cache.lastAt + WARM_AFTER_MS }
}

/** Why the cache can't be kept warm now, or null when it can. */
function whyNoWarm(cache: ContextCacheCache, now: number): string | null {
  if (cache.ttlMs !== TTL_1H) return '5-minute cache'
  if (cache.lastAt === null) return 'nothing cached'
  if (now - cache.lastAt >= cache.ttlMs) return 'cache already cold'
  return null
}

async function stopWarm($: EngineInterface, why: string) {
  autoHeld = true
  await update($, warmUntilAtom, () => null)
  await $.store.set('warmRun', null)
  $.ui.toast(`Warm off, ${why}.`)
}

// Auto-warm: Warm switches itself on once you have been quiet 55 minutes with
// a context over the size /cache-autowarm set (off until set). Stop, or warming
// stopping by itself, holds it off until the next reply.
const AUTO_STEPS = [0, 200_000, 300_000, 500_000]
let autoHeld = false
/** The reply (cache.lastAt) the 5-minutes-left notice was raised for. */
let coldSoonFor: number | null = null

async function autoWarmAt($: EngineInterface): Promise<number> {
  const v = await $.store.get('autoWarmAt')
  return typeof v === 'number' && v > 0 ? v : 0
}

/** 5 minutes left and nothing will keep the cache: a notification, or a toast where nothing can notify (the desktop). */
async function coldSoon($: EngineInterface, snap: ContextCacheSnapshot, now: number) {
  const { cache, context } = snap
  if (cache.lastAt === null || coldSoonFor === cache.lastAt) return
  coldSoonFor = cache.lastAt
  const price = priceOf(snap.model, cache.ttlMs)
  const text =
    `Cache cold in ${fmtSpan(cache.lastAt + cache.ttlMs - now)}` +
    (price && context ? `, ${fmtUsd(context.used * price.write)} to rebuild.` : '.')
  const sent = await $.ui.notify(text, { title: 'Context & cache' }).catch(() => ({ isSent: false as const }))
  if (!sent.isSent) $.ui.toast(text)
}

/** Checked every 15s: pings once the cache is 55 min old while warming; otherwise auto-warm or the 5-minutes-left notice. */
async function warmTick($: EngineInterface) {
  if (warmInFlight) return
  let until = await read($, warmUntilAtom)
  const now = await $.clock.now()
  const snap = await current($)
  const { cache } = snap
  if (until === null) {
    if (cache.lastAt === null || whyNoWarm(cache, now) || now - cache.lastAt < WARM_AFTER_MS) return
    const at = await autoWarmAt($)
    if (autoHeld || at === 0 || (snap.context?.used ?? 0) < at) return coldSoon($, snap, now)
    until = now + WARM_FOR_MS
    await startWarmRun($, now, until)
    await update($, warmUntilAtom, () => until)
    $.ui.toast(`Auto-warm on, context ${fmtTokens(snap.context!.used)}.`)
  }
  if (now >= until) return stopWarm($, 'ran 8h')
  const why = whyNoWarm(cache, now)
  if (why) return stopWarm($, why)
  if (now - cache.lastAt! < WARM_AFTER_MS) return
  warmInFlight = true
  try {
    const r = await $.model.fork({ prompt: WARM_PROMPT })
    if (!r.isAnswered && r.reason === 'nothing-to-fork') return stopWarm($, 'nothing cached')
    const u = 'usage' in r ? r.usage : undefined
    if (u && u.cache_read_input_tokens > 0) {
      const at = await $.clock.now()
      lastPing = { at, read: u.cache_read_input_tokens }
      const run = (await $.store.get('warmRun')) as WarmRun | null | undefined
      if (run) await $.store.set('warmRun', { ...run, pings: [...run.pings, lastPing] })
      await patchCache($, { lastAt: at })
      // A ping pays a cache read and spares the re-write going cold would cost.
      const price = priceOf((await current($)).model, cache.ttlMs)
      await addToTally($, { pings: 1, pingUsd: price ? u.cache_read_input_tokens * (price.write - price.read) : 0 })
    }
    else if (u && u.cache_creation_input_tokens > 0) await stopWarm($, 'ping missed the cache')
    // else an API error: the next tick retries while the cache is still warm
  } finally {
    warmInFlight = false
  }
}

/** Clear, Compact and Warm/Stop. None hides the notice row: it stays on whatever the cache holds. */
async function actionsFor($: EngineInterface, isWorking: boolean): Promise<Actions> {
  const isWarming = (await read($, warmUntilAtom)) !== null
  return {
    isWarming,
    warm: async () => {
      if ((await read($, warmUntilAtom)) !== null) {
        autoHeld = true
        await update($, warmUntilAtom, () => null)
        $.ui.toast('Warm off.')
        return
      }
      const now = await $.clock.now()
      const why = whyNoWarm((await current($)).cache, now)
      if (why) {
        $.ui.toast(`Can't warm, ${why}.`)
        return
      }
      await startWarmRun($, now, now + WARM_FOR_MS)
      await update($, warmUntilAtom, () => now + WARM_FOR_MS)
      const snap = await current($)
      const price = priceOf(snap.model, snap.cache.ttlMs)
      const cost =
        price && snap.context
          ? ` ${fmtUsd(snap.context.used * price.read)} a ping, saves ${fmtUsd(snap.context.used * price.write)}.`
          : ''
      $.ui.toast(`Warm on for 8h.${cost}`)
    },
    clear: async () => {
      if (isWorking) $.ui.toast('Clear after this turn.')
      try {
        await $.command.run({ command: 'clear' })
      } catch {
        $.ui.toast('/clear failed.')
      }
    },
    // Queued like Clear: $.session.compact() rejects whenever the engine is not idle.
    // Our session.compact hook resets the cache once it runs.
    compact: async () => {
      if (isWorking) $.ui.toast('Compact after this turn.')
      try {
        await $.command.run({ command: 'compact' })
      } catch (err) {
        $.ui.toast(`/compact failed: ${err instanceof Error ? err.message : String(err)}`)
      }
    },
  }
}

export const register: Register = on => {
  // ── Session lifecycle ──────────────────────────────────────────────────

  on('session.start', async ($, e, next) => {
    cwd = e.cwd
    // One command each: the desktop composer drops anything typed after a slash command's name.
    for (const c of COMMANDS) await $.command.register(c)
    const storedPx = await $.store.get('pxPerCell')
    if (typeof storedPx === 'number' && storedPx > 0) await update($, pxPerCellAtom, () => storedPx)
    if ((await $.store.get('isMini')) === true) await update($, miniAtom, () => true)
    const initial = await current($)
    await update($, snapshotAtom, prev => prev ?? initial)
    void refresh($)
    // Started from the phone: the pane is how the panel shows there.
    if (await hasMobile($)) void $.ui.open({ id: PANE, title: 'Context & cache' }).catch(() => undefined)
    // The countdown: checked once a second, redrawn only when a figure the
    // panel shows would change (a 60m TTL moves a whole percent every 36s; a
    // 5m one shows seconds, so it redraws every second).
    let lastShown = ''
    $.clock.every(1000, () => {
      void (async () => {
        const [snap, hidden] = await Promise.all([read($, snapshotAtom), read($, hiddenAtom)])
        if (hidden || !snap) return
        const now = await $.clock.now()
        const c = cacheView(snap.cache, now)
        const lit = Object.values(snap.pulse ?? {}).map(at => (isPulseLit(at, now) ? 1 : 0)).join('')
        const shown = `${c.state}|${pct(c.warmth * 100)}|${c.detail}|${c.state === 'cooling' ? noticeText(c, snap.context, snap.cache.ttlMs) : ''}|${lit}`
        if (shown === lastShown) return
        lastShown = shown
        await update($, nowAtom, () => now)
      })().catch(() => undefined)
    })
    $.clock.every(ACCOUNT_EVERY_MS, () => void refresh($, false))
    $.clock.every(15_000, () => void warmTick($).catch(() => undefined))
    return next(e)
  })

  // Resumed: the transcript says how long ago the last response was.
  on('classic.SessionStart', async ($, e, next) => {
    const now = await $.clock.now()
    if ((e.source === 'resume' || e.source === 'fork') && typeof e.seconds_since_last_response === 'number') {
      await patchCache($, { lastAt: now - e.seconds_since_last_response * 1000 })
    } else if (e.source === 'clear' || e.source === 'compact') {
      await patchCache($, { lastAt: null, hitRate: null })
    }
    void learnTtl($, e.transcript_path)
    return next(e)
  }).catch((_$, e, next) => next(e))

  // Each main-thread response writes/reads the cache as it lands, so a long
  // turn (or the first one after /clear) does not sit at "Empty" until it ends.
  on('turn.step', async function* ($, e, next) {
    const r = yield* next(e)
    const u = r.usage
    if (e.agentId === undefined && u) {
      autoHeld = false // a reply: auto-warm may act again on the next quiet spell
      const total = u.cache_read_input_tokens + u.cache_creation_input_tokens + u.input_tokens
      void $.clock
        .now()
        .then(now => patchCache($, { lastAt: now, hitRate: total > 0 ? u.cache_read_input_tokens / total : null }))
        .then(() => update($, snapshotAtom, s => (s?.saved ? { ...s, saved: null } : s)))
        .catch(() => undefined)
    }
    return r
  })

  // A turn of the main conversation ended: its requests just wrote/read the cache.
  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined) {
      turnNo += 1
      const now = await $.clock.now()
      const u = e.usage
      const total = u ? u.cache_read_input_tokens + u.cache_creation_input_tokens + u.input_tokens : 0
      await patchCache($, {
        lastAt: u ? now : (await current($)).cache.lastAt,
        hitRate: u && total > 0 ? u.cache_read_input_tokens / total : (await current($)).cache.hitRate,
      })
      void refresh($)
    }
    return result
  })

  // You're back: your own message keeps the cache warm from here, so warming stops.
  // turn.start, not prompt.submit: the desktop app's messages skip prompt.submit.
  on('turn.start', async ($, e, next) => {
    if (!warmInFlight && (await read($, warmUntilAtom)) !== null) {
      await update($, warmUntilAtom, () => null)
      $.ui.toast('Welcome back. Warm off.')
    }
    return next(e)
  }).catch((_$, e, next) => next(e))

  // After each turn, read which TTL the responses were cached with.
  on('classic.Stop', ($, e, next) => {
    void learnTtl($, e.transcript_path)
    return next(e)
  }).catch((_$, e, next) => next(e))

  // The engine reports the TTL itself on a model switch; a switch also forfeits the cache.
  // Before a switch you asked for: a warm cache would be thrown away, so ask
  // first, with what the next message pays to write it again.
  on('classic.PreModelSwitch', async ($, e, next) => {
    const result = await next(e)
    if (!e.prompt_cache_warm || e.context_tokens <= 0 || result.permissionDecision) return result
    const usd = e.pricing === 'default' ? '' : ` for ${fmtUsd(e.estimated_cache_write_usd)}`
    return {
      ...result,
      permissionDecision: 'ask' as const,
      permissionDecisionReason: `Switching model throws away the warm cache: the next message re-writes ${fmtTokens(e.context_tokens)}${usd}. Switch anyway?`,
    }
  }).catch((_$, e, next) => next(e))

  on('classic.PostModelSwitch', async ($, e, next) => {
    // A switch nobody was asked about (an automatic fallback) still throws a
    // warm cache away: say what the next message pays to write it again.
    if (e.prompt_cache_warm && e.context_tokens > 0 && e.source === 'auto') {
      const usd = e.pricing === 'default' ? '' : ` Next message ${fmtUsd(e.estimated_cache_write_usd)}.`
      $.ui.toast(`Model switched, cache lost.${usd}`)
    }
    await setTtl($, e.cache_ttl === '5m' ? TTL_5M : TTL_1H)
    await patchCache($, { lastAt: null, hitRate: null })
    void refresh($)
    return next(e)
  }).catch((_$, e, next) => next(e))

  // Usage figures moved (context fill, a limit window).
  on('session.measure', ($, e, next) => {
    void refresh($)
    return next(e)
  })

  // A compaction replaces the conversation: nothing of the new one is cached yet.
  on('session.compact', async ($, e, next) => {
    const before = (await current($)).context?.used ?? null
    const result = await next(e)
    if (e.trigger !== 'precompute' && !('skip' in result)) {
      await patchCache($, { lastAt: null, hitRate: null })
      await noteSaved($, 'compact', before)
    }
    return result
  }).catch((_$, e, next) => next(e))

  // /clear starts a fresh conversation in the same process.
  on('session.end', async ($, e, next) => {
    const before = (await current($)).context?.used ?? null
    const result = await next(e)
    if (e.reason === 'clear') {
      await patchCache($, { lastAt: null, hitRate: null })
      await noteSaved($, 'clear', before)
    }
    return result
  })

  // ── /cache, /cache-status, /cache-pane, /cache-refresh, /cache-scale ────

  on('command.run', { command: 'cache-status' }, async $ => ({ text: await statusReport($) }))

  on('command.run', { command: 'cache-refresh' }, async $ => {
    await refresh($, true)
    return { text: 'Context & cache panel refreshed.' }
  })

  on('command.run', { command: 'cache-scale' }, async ($, e) => {
    const was = await read($, pxPerCellAtom)
    const typed = Number(e.args.trim())
    // No number typed (or none delivered): step through 7 … 9.5 and round.
    const n = Number.isFinite(typed) && typed > 0 ? typed : was >= 9.5 ? 7 : Math.round((was + 0.5) * 2) / 2
    await $.store.set('pxPerCell', n)
    await update($, pxPerCellAtom, () => n)
    return { text: `Desktop now draws at ${n} px per cell (was ${was}). Run it again to step up; /cache-scale <px> sets it outright.` }
  })

  on('command.run', { command: 'cache-mini' }, async $ => {
    const isMini = !(await read($, miniAtom))
    await $.store.set('isMini', isMini)
    await update($, miniAtom, () => isMini)
    return {
      text: isMini
        ? 'Context & cache panel: one line (context, cache, next message). /cache-mini again for the whole card.'
        : 'Context & cache panel: the whole card again.',
    }
  })

  on('command.run', { command: 'cache-autowarm' }, async ($, e) => {
    const was = await autoWarmAt($)
    const typed = e.args.trim() === '' ? NaN : Number(e.args.trim())
    // No number typed (or none delivered): the next step after the current one.
    const n = Number.isFinite(typed) && typed >= 0 ? Math.round(typed * 1000) : AUTO_STEPS[(AUTO_STEPS.indexOf(was) + 1) % AUTO_STEPS.length]!
    await $.store.set('autoWarmAt', n)
    const before = was === 0 ? 'off' : fmtTokens(was)
    if (n === 0) return { text: `Auto-warm is off (was ${before}).` }
    return {
      text: `Auto-warm: Warm switches itself on when the context is over ${fmtTokens(n)} and you have been quiet ${WARM_AFTER_MS / 60_000} minutes (was ${before}). Each ping reads the cache; /cache-autowarm 0 turns it off.`,
    }
  })

  on('command.run', { command: 'cache-pane' }, async $ => {
    await update($, hiddenAtom, () => false)
    void refresh($)
    await $.ui.open({ id: PANE, title: 'Context & cache' })
    return { text: 'Context & cache panel opened.' }
  })

  on('command.run', { command: 'cache' }, async $ => {
    const isHidden = await read($, hiddenAtom)
    await update($, hiddenAtom, () => !isHidden)
    if (isHidden) {
      void refresh($)
      // Phones have no band above the prompt: show it there as a pane.
      if (await hasMobile($)) await $.ui.open({ id: PANE, title: 'Context & cache' })
      return { text: 'Context & cache panel shown.' }
    }
    await $.ui.close({ id: PANE }).catch(() => undefined)
    return { text: 'Context & cache panel hidden. /cache shows it again.' }
  })

  // A phone joined the session: open the panel as a pane there.
  on('session.attach', async ($, e, next) => {
    const result = await next(e)
    attached.push(e.surface)
    if (e.surface === 'mobile' && !(await read($, hiddenAtom))) {
      void $.ui.open({ id: PANE, title: 'Context & cache' }).catch(() => undefined)
    }
    return result
  })

  // ── The band above the prompt (terminal, desktop) ──────────────────────

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    noteDraw('AbovePrompt', e.surface)
    if (e.props.hasSurvey) return next(e)
    if (e.props.view.agentId !== undefined) return next(e)
    const E = $.ui.resolve(e)
    if (await read($, miniAtom)) {
      const [snap, hidden, tick] = await Promise.all([read($, snapshotAtom), read($, hiddenAtom), read($, nowAtom)])
      if (hidden || !snap) return next(e)
      const now = Math.max(tick, snap.updatedAt)
      // paddingX 1 each side
      return renderMini(E, miniLine(snap, now, e.props.bodyColumns - 2), cacheView(snap.cache, now).color)
    }
    if (e.surface === 'terminal') {
      const vm = await panelModel($, e.props.bodyColumns, e.props.maxRows, terminalNoticeChars(e.props.bodyColumns))
      if (!vm) return next(e)
      return renderTerminal(E as Parameters<typeof renderTerminal>[0], vm, e.props.bodyColumns, (await actionsFor($, e.props.isWorking)))
    }
    if (e.surface === 'desktop' || e.surface === 'vscode') {
      const px = await widthPx($, e.props.bodyColumns)
      const vm = await panelModel($, designCells(px), e.props.maxRows)
      if (!vm) return next(e)
      return renderDesktop(E as Parameters<typeof renderDesktop>[0], vm, px, (await actionsFor($, e.props.isWorking)))
    }
    return next(e)
  })

  // ── The same panel as a pane (every surface; the phone's way to see it) ─

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    noteDraw('Pane', e.surface)
    const E = $.ui.resolve(e)
    const { Text } = E
    const rows = Math.max(e.props.scroll.bodyRows, 12)
    if (e.surface === 'terminal') {
      const vm = await panelModel($, e.props.bodyColumns, rows, terminalNoticeChars(e.props.bodyColumns))
      if (!vm) return <Text dimColor>Reading usage…</Text>
      return renderTerminal(E as Parameters<typeof renderTerminal>[0], vm, e.props.bodyColumns, (await actionsFor($, false)))
    }
    const px = await widthPx($, e.props.bodyColumns)
    const vm = await panelModel($, designCells(px), rows)
    if (!vm) return <Text dimColor>Reading usage…</Text>
    return renderDesktop(E as Parameters<typeof renderDesktop>[0], vm, px, (await actionsFor($, false)))
  })
}

