// Pure maths and copy for the context-cache panel: no `$`, no drawing.
// Everything here takes real figures in and returns what the panel shows.

import type { ContextCategory, SessionMessage, SessionRateLimit } from 'claude-code'

import type {
  ContextCacheCache,
  ContextCacheContext,
  ContextCacheGroup,
  ContextCacheLimit,
  ContextCacheLimitKind,
  ContextCacheSaved,
  ContextCacheSnapshot,
  ContextCacheWarming,
} from '../types'

// ── Design tokens ──────────────────────────────────────────────────────────

export const TOKENS = {
  card: '#222120',
  border: '#34322e',
  borderStrong: '#4a4741',
  track: '#2f2d2a',
  ringTrack: '#3a3835',
  text: '#ece9e2',
  text2: '#b9b5ab',
  /** The notice line: text2 lifted 20%. */
  notice: '#ded9cd',
  /** The dot beside a notice that reports what Clear or Compact saved. */
  saved: '#4fae6a',
  text3: '#8a867d',
  text4: '#7d7970',
  tick: '#ece9e2',
  buttonText: '#1b1a18',
  /** The context percentage in "112k / 1M (11%)", bold. */
  strong: '#ffffff',
  /** The free-token count in the legend, a step lighter than its "Free" label. */
  freeTokens: '#c7c1b3',
} as const

export const GROUP_COLORS: Record<ContextCacheGroup, string> = {
  system: '#6f6b64',
  tools: '#7050b8',
  files: '#2f6bd6',
  messages: '#c2562f',
}

export const GROUP_LABELS: Record<ContextCacheGroup, string> = {
  system: 'System',
  tools: 'Tools',
  files: 'Files',
  messages: 'Messages',
}

export const GROUPS: readonly ContextCacheGroup[] = ['system', 'tools', 'files', 'messages']

export const LIMIT_COLORS: Record<ContextCacheLimitKind, { bright: string; dark: string }> = {
  session: { bright: '#4fae6a', dark: '#2c5a3a' },
  weekly: { bright: '#3b7be0', dark: '#2b4a80' },
  fable: { bright: '#8a6fc0', dark: '#4a4160' },
}
export const AMBER = { bright: '#e0a84f', dark: '#6b5428' }
export const RED = { bright: '#e5604f', dark: '#6b2f2a' }

export const LIMIT_TITLES: Record<ContextCacheLimitKind, string> = {
  session: 'Current session',
  weekly: 'Weekly limits',
  fable: 'Fable',
}

export const CACHE_COLORS = {
  warm: '#e8833a',
  cooling: '#e0a84f',
  cold: '#4f9be8',
  empty: '#7d7970',
} as const

export const HOUR = 3_600_000
export const FIVE_HOURS = 5 * HOUR
export const SEVEN_DAYS = 7 * 24 * HOUR
export const TTL_5M = 5 * 60_000
export const TTL_1H = HOUR

// ── Formatting ─────────────────────────────────────────────────────────────

/** 452000 → "452k", 1000000 → "1M", 1500000 → "1.5M", 640 → "640". */
// ── Prices ─────────────────────────────────────────────────────────────────

// ponytail: list prices copied by hand ($ per million tokens: input, cache
// read), as of 2026-10-13; update when Anthropic changes them. Matched by
// prefix, most specific first, so `claude-opus-5-5[1m]` finds Opus 5.5.
const PRICES: [string, number, number][] = [
  ['claude-fable-5-1', 10, 0.25],
  ['claude-mythos-5-1', 10, 0.25],
  ['claude-fable-5', 10, 1],
  ['claude-mythos-5', 10, 1],
  ['claude-opus-5-5', 4, 0.2],
  ['claude-opus-5', 5, 0.5],
  ['claude-opus-4', 5, 0.5],
  ['claude-sonnet-5', 2, 0.2],
  ['claude-sonnet-4', 3, 0.3],
  ['claude-haiku-5-5', 0.1, 0.01],
  ['claude-haiku-4', 1, 0.1],
]

/** $ per token to read the cache, and to write it (2× input for the 1-hour cache, 1.25× for 5 minutes); null for an unknown model. */
export type Price = { read: number; write: number }

/** The list prices in $ per million tokens, or null for a model missing from the list. */
export function listPrice(model: string | null | undefined): { input: number; read: number } | null {
  const row = model ? PRICES.find(([p]) => model.startsWith(p)) : undefined
  return row ? { input: row[1], read: row[2] } : null
}

export function priceOf(model: string | null | undefined, ttlMs: number): Price | null {
  const list = listPrice(model)
  if (!list) return null
  return { read: list.read / 1e6, write: (list.input * (ttlMs === TTL_5M ? 1.25 : 2)) / 1e6 }
}

/** "≈$3.61", "≈$0.09", "<$0.01". */
export function fmtUsd(n: number): string {
  if (n < 0.005) return '<$0.01'
  return `≈$${n < 100 ? n.toFixed(2) : Math.round(n)}`
}

export function fmtTokens(n: number): string {
  if (n >= 1_000_000) {
    const m = n / 1_000_000
    return `${Number.isInteger(m) ? m : m.toFixed(1).replace(/\.0$/, '')}M`
  }
  if (n >= 1000) return `${Math.round(n / 1000)}k`
  return String(Math.max(0, Math.round(n)))
}

/** Whole percent, never NaN. */
export function pct(n: number): number {
  return Number.isFinite(n) ? Math.round(n) : 0
}

/** 7_920_000 → "2h 12m"; 200_000 → "3m 20s"; 45_000 → "45s"; days when ≥ 24h. */
export function fmtSpan(ms: number, withSeconds = false): string {
  const s = Math.max(0, Math.round(ms / 1000))
  const d = Math.floor(s / 86400)
  const h = Math.floor((s % 86400) / 3600)
  const m = Math.floor((s % 3600) / 60)
  const sec = s % 60
  if (d > 0) return `${d}d ${h}h`
  if (h > 0) return `${h}h ${m}m`
  if (withSeconds) return m > 0 ? `${m}m ${sec}s` : `${sec}s`
  return `${m}m`
}

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

/** "Resets in 2h 12m" inside a day, else "Resets Sun 11:00 pm" (local time). */
export function fmtReset(resetsAt: number | null, now: number): string {
  if (resetsAt === null) return 'Reset time not reported'
  const left = resetsAt - now
  if (left <= 0) return 'Resetting now'
  if (left < 24 * HOUR) return `Resets in ${fmtSpan(left)}`
  return `Resets ${DAYS[new Date(resetsAt).getDay()]} ${fmtClock(resetsAt)}`
}

/** "11:05 pm" (local time). */
export function fmtClock(at: number): string {
  const d = new Date(at)
  const h24 = d.getHours()
  const h12 = h24 % 12 === 0 ? 12 : h24 % 12
  return `${h12}:${String(d.getMinutes()).padStart(2, '0')} ${h24 < 12 ? 'am' : 'pm'}`
}

// ── Context ────────────────────────────────────────────────────────────────

/** Tools whose results are file contents, for the Files share of Messages. */
const FILE_TOOLS = new Set(['Read', 'NotebookRead'])

/**
 * The share of the conversation's text that is file contents the model read,
 * 0 to 1: the Files segment is that share of the Messages row's real tokens.
 */
export function fileShareOf(messages: readonly SessionMessage[]): number {
  let total = 0
  let files = 0
  for (const m of messages) {
    total += m.text.length
    for (const use of m.toolUses) {
      const len = (use.text ?? '').length + JSON.stringify(use.input ?? {}).length
      total += len
      if (FILE_TOOLS.has(use.tool)) files += (use.text ?? '').length
    }
  }
  return total > 0 ? Math.min(1, files / total) : 0
}

/** Which of the four groups a /context row belongs to. */
export function groupOf(name: string): ContextCacheGroup {
  if (/message/i.test(name)) return 'messages'
  if (/tool|mcp|agent|skill|command/i.test(name)) return 'tools'
  return 'system'
}

/**
 * The context row's figures: /context's categories grouped into four and
 * scaled so they sum to the real token count the last response reported.
 */
export function buildContext(args: {
  categories: readonly ContextCategory[]
  realTokens: number | undefined
  window: number
  autoCompactAt: number | undefined
  isAutoCompactEnabled: boolean
  fileShare: number
}): ContextCacheContext {
  const raw: Record<ContextCacheGroup, number> = { system: 0, tools: 0, files: 0, messages: 0 }
  for (const c of args.categories) {
    if (c.kind !== 'used') continue
    raw[groupOf(c.name)] += c.tokens
  }
  const fileTokens = Math.round(raw.messages * args.fileShare)
  raw.files = fileTokens
  raw.messages -= fileTokens
  const estimate = GROUPS.reduce((s, g) => s + raw[g], 0)
  const used = args.realTokens ?? estimate
  const k = estimate > 0 ? used / estimate : 0
  const parts = { system: 0, tools: 0, files: 0, messages: 0 } as Record<ContextCacheGroup, number>
  for (const g of GROUPS) parts[g] = Math.round(raw[g] * k)
  return {
    used,
    window: args.window,
    autoCompactAt: args.isAutoCompactEnabled && args.autoCompactAt ? args.autoCompactAt : null,
    parts,
  }
}

// ── Limits ─────────────────────────────────────────────────────────────────

type Found = { path: string[]; node: Record<string, unknown>; usage: number }

function walk(node: unknown, path: string[], out: Found[]): void {
  if (Array.isArray(node)) {
    node.forEach((n, i) => walk(n, [...path, String(i)], out))
    return
  }
  if (node === null || typeof node !== 'object') return
  const obj = node as Record<string, unknown>
  // five_hour / seven_day say `utilization`; the limits[] items (the per-model windows) say `percent`.
  const u = obj['utilization'] ?? obj['percent'] ?? obj['percent_used'] ?? obj['used_percent']
  if (typeof u === 'number') {
    out.push({ path, node: obj, usage: u })
    return
  }
  for (const [k, v] of Object.entries(obj)) walk(v, [...path, k], out)
}

const isFable = (f: Found) => /fable/i.test(f.path.join('.')) || /fable/i.test(JSON.stringify(f.node))

/** Every window with a utilization figure in the account usage JSON, for /cache status. */
export function usageWindowsOf(json: unknown): { path: string; usage: number; isFable: boolean }[] {
  const found: Found[] = []
  walk(json, [], found)
  return found.map(f => ({ path: f.path.join('.'), usage: f.usage, isFable: isFable(f) }))
}

function toEpochMs(v: unknown): number | null {
  if (typeof v === 'number') return v < 1e12 ? v * 1000 : v
  if (typeof v === 'string') {
    const t = Date.parse(v)
    return Number.isNaN(t) ? null : t
  }
  return null
}

/**
 * Reads the account usage endpoint's JSON (api.anthropic.com/api/oauth/usage),
 * the same source /usage draws on: `five_hour` is the current session,
 * `seven_day` the weekly limit, and Fable is the `limits[]` item of kind
 * `weekly_scoped` whose `scope.model.display_name` is "Fable" (an item with
 * `scope: null` repeats `seven_day`). Matching by name rather than a fixed
 * key keeps it working if the key moves.
 */
export function parseAccountUsage(json: unknown): ContextCacheLimit[] {
  const found: Found[] = []
  walk(json, [], found)
  const out: ContextCacheLimit[] = []
  const take = (kind: ContextCacheLimitKind, f: Found | undefined, windowMs: number) => {
    if (!f) return
    out.push({
      kind,
      usage: Math.max(0, Math.min(100, f.usage)),
      resetsAt: toEpochMs(f.node['resets_at'] ?? f.node['resetsAt']),
      windowMs,
    })
  }
  const keyOf = (f: Found) => f.path[f.path.length - 1] ?? ''
  take('session', found.find(f => keyOf(f) === 'five_hour'), FIVE_HOURS)
  take('weekly', found.find(f => keyOf(f) === 'seven_day'), SEVEN_DAYS)
  const fable = found.filter(isFable).sort((a, b) => b.usage - a.usage)[0]
  take('fable', fable, SEVEN_DAYS)
  return out
}

/** The engine's own per-response rate-limit readings, as a fallback. */
export function limitsFromResponse(rateLimits: readonly SessionRateLimit[]): ContextCacheLimit[] {
  const out: ContextCacheLimit[] = []
  for (const r of rateLimits) {
    const kind: ContextCacheLimitKind | null =
      r.kind === 'five_hour' ? 'session' : r.kind === 'seven_day' ? 'weekly' : /fable/i.test(r.kind) ? 'fable' : null
    if (!kind) continue
    out.push({
      kind,
      usage: Math.max(0, Math.min(100, r.percentUsed)),
      resetsAt: r.resetsAt ? toEpochMs(r.resetsAt) : null,
      windowMs: kind === 'session' ? FIVE_HOURS : SEVEN_DAYS,
    })
  }
  return out
}

export type LimitTone = 'normal' | 'amber' | 'red'

export type LimitView = {
  kind: ContextCacheLimitKind
  title: string
  /** Null when this limit has no reading at all. */
  usage: number | null
  time: number | null
  tone: LimitTone
  bright: string
  dark: string
  reset: string
}

/** Percent of the window that has elapsed, from its reset time. */
export function timePct(limit: ContextCacheLimit, now: number): number | null {
  if (limit.resetsAt === null) return null
  const elapsed = limit.windowMs - (limit.resetsAt - now)
  return Math.max(0, Math.min(100, (elapsed / limit.windowMs) * 100))
}

/** Red at ≥ 90% used; amber when > 15 points and > 1.4× ahead of time. */
export function toneOf(usage: number, time: number | null): LimitTone {
  if (usage >= 90) return 'red'
  const t = time ?? 0
  if (usage - t > 15 && (t === 0 || usage / t > 1.4)) return 'amber'
  return 'normal'
}

/** How long a bar pulses after turning amber or red: lit, off, lit, off, a second each. */
export const PULSE_MS = 4000

/** Whether a pulse that began at `at` is lit at `now`. */
export function isPulseLit(at: number | undefined, now: number): boolean {
  if (at === undefined) return false
  const t = now - at
  return t >= 0 && t < PULSE_MS && Math.floor(t / 1000) % 2 === 0
}

export function limitView(kind: ContextCacheLimitKind, limit: ContextCacheLimit | undefined, now: number, pulseAt?: number): LimitView {
  if (!limit) {
    const base = LIMIT_COLORS[kind]
    return { kind, title: LIMIT_TITLES[kind], usage: null, time: null, tone: 'normal', ...base, reset: 'No reading yet' }
  }
  const time = timePct(limit, now)
  const tone = toneOf(limit.usage, time)
  const colors = tone === 'red' ? RED : tone === 'amber' ? AMBER : LIMIT_COLORS[kind]
  return {
    kind,
    title: LIMIT_TITLES[kind],
    usage: limit.usage,
    time,
    tone,
    ...colors,
    ...(isPulseLit(pulseAt, now) ? { bright: mix(colors.bright, '#ffffff', 0.5) } : {}),
    reset: fmtReset(limit.resetsAt, now),
  }
}

const SHORT_TITLES: Record<ContextCacheLimitKind, string> = { session: 'Session', weekly: 'Weekly', fable: 'Fable' }

/** The one-time toast as a limit reaches 90%: "Weekly at 90%, resets Sat 11:00 pm." */
export function limitToast(limit: ContextCacheLimit, now: number): string {
  const reset = fmtReset(limit.resetsAt, now)
  return `${SHORT_TITLES[limit.kind]} at ${pct(limit.usage)}%, ${reset.charAt(0).toLowerCase()}${reset.slice(1)}.`
}

// ── Cache ──────────────────────────────────────────────────────────────────

export type CacheState = 'warm' | 'cooling' | 'cold' | 'empty'

export type CacheView = {
  state: CacheState
  /** Remaining TTL ÷ TTL, 0 to 1. */
  warmth: number
  remainingMs: number
  color: string
  label: string
  hit: number | null
  detail: string
}

/** Warm > 25% of the TTL left, cooling 1–25%, cold at 0; empty with nothing cached. */
export function cacheView(cache: ContextCacheCache, now: number): CacheView {
  const ttl = cache.ttlMs
  const hit = cache.hitRate === null ? null : cache.hitRate * 100
  if (cache.lastAt === null) {
    return {
      state: 'empty',
      warmth: 0,
      remainingMs: 0,
      color: CACHE_COLORS.empty,
      label: 'Empty',
      hit,
      detail: 'Nothing cached yet',
    }
  }
  // Capped at the TTL: a reply or ping stamps lastAt with a fresher clock than
  // the drawing's `now`, which would otherwise read as 103% and "61m left of 60m".
  const remainingMs = Math.max(0, Math.min(ttl, cache.lastAt + ttl - now))
  const warmth = ttl > 0 ? remainingMs / ttl : 0
  const state: CacheState = warmth <= 0 ? 'cold' : warmth > 0.25 ? 'warm' : 'cooling'
  const short = ttl < 10 * 60_000
  const ttlText = `${Math.round(ttl / 60_000)}m`
  const detail =
    state === 'cold'
      ? (() => {
          const ago = now - (cache.lastAt + ttl)
          return ago < 60_000 ? 'Expired just now' : `Expired ${fmtSpan(ago)} ago`
        })()
      : short
        ? `${fmtSpan(remainingMs, true)} left of ${ttlText}`
        : `${Math.max(1, Math.round(remainingMs / 60_000))}m left of ${ttlText}`
  return {
    state,
    warmth,
    remainingMs,
    color: CACHE_COLORS[state],
    label: state === 'warm' ? 'Warm' : state === 'cooling' ? 'Cooling' : 'Cold',
    hit,
    detail,
  }
}

/**
 * The notice line's copy. Always a line: the row with Clear / Compact / Warm never hides.
 * `short`: the wording for every layout below the widest, short enough to stay on one line.
 */
export function noticeText(cache: CacheView, context: ContextCacheContext | null, ttlMs: number, short = false, price: Price | null = null): string {
  if (!context) return cache.state === 'empty' ? 'Cache empty: nothing cached yet.' : `Cache ${cache.label.toLowerCase()}: reading context size…`
  const tokens = fmtTokens(context.used)
  // With a known price: what reading the cache costs, and what writing it again costs.
  const read = price ? fmtUsd(context.used * price.read) : ''
  const write = price ? fmtUsd(context.used * price.write) : ''
  const more = price ? fmtUsd(context.used * (price.write - price.read)) : ''
  if (cache.state === 'empty') {
    if (short) return price ? `Cache empty: writes ${tokens} (${write}).` : `Cache empty: writes ${tokens}.`
    return price ? `Cache empty: next message writes ${tokens} to cache for ${write}.` : `Cache empty: next message writes ${tokens} to cache.`
  }
  if (cache.state === 'warm') {
    const usedPct = (context.used / context.window) * 100
    if (context.autoCompactAt !== null && usedPct >= 85) {
      const away = Math.max(0, pct((context.autoCompactAt / context.window) * 100 - usedPct))
      if (short) return `Warm: reuses ${tokens}. Compact ${away}% away.`
      return price
        ? `Cache warm: next message reuses ${tokens} for ${read}. Auto-compact is ${away}% away.`
        : `Cache warm: next message reuses ${tokens}. Auto-compact is ${away}% away.`
    }
    if (short) return price ? `Cache warm: reuses ${tokens} (${read}).` : `Cache warm: reuses ${tokens}.`
    return price
      ? `Cache warm: next message reuses ${tokens} for ${read} (${write} if it goes cold).`
      : `Cache warm: next message reuses ${tokens} from cache.`
  }
  if (cache.state === 'cooling') {
    const within =
      ttlMs < 10 * 60_000 ? fmtSpan(cache.remainingMs, true) : `${Math.max(1, Math.round(cache.remainingMs / 60_000))}m`
    if (short) return price ? `Cooling: send within ${within} (${more}).` : `Cooling: send within ${within}.`
    return price
      ? `Cache cooling: send within ${within} to keep ${tokens} cached, or pay ${more} more.`
      : `Cache cooling: send within ${within} to keep ${tokens} cached.`
  }
  if (short) return price ? `Cache cold: re-reads ${tokens} (${write}).` : `Cache cold: re-reads ${tokens}.`
  return price ? `Cache cold: next message re-reads ${tokens} for ${write}. Clear is free.` : `Cache cold: next message re-reads ${tokens}. Clear is free.`
}

/**
 * The notice after a Clear or Compact, until the next reply lands: a bold lead
 * (what was taken out) and the rest (what each later message now costs less).
 */
export function savedNotice(saved: ContextCacheSaved, price: Price | null, short = false): { lead: string; rest: string } {
  const freed = Math.max(0, saved.before - saved.after)
  const lead =
    saved.kind === 'clear' ? `Cleared ${fmtTokens(saved.before)}.` : `Compacted ${fmtTokens(saved.before)} → ${fmtTokens(saved.after)}.`
  if (!price) return { lead, rest: short ? '' : ` Each message now sends ${fmtTokens(freed)} fewer tokens.` }
  const warm = fmtUsd(freed * price.read)
  const cold = fmtUsd(freed * price.write)
  if (short) return { lead, rest: ` ${cold} less a message.` }
  return saved.kind === 'clear'
    ? { lead, rest: ` Next message costs ${cold} less, or ${warm} less while the cache is warm.` }
    : { lead, rest: ` Each message sends ${fmtTokens(freed)} fewer: ${warm} less warm, ${cold} after a break.` }
}

/** While Warm runs, in place of the cache notice: the last ping and the next, long, short and tiny. */
export function warmNotice(w: ContextCacheWarming, context: ContextCacheContext | null): string[] {
  const next = fmtClock(w.nextAt)
  const p = w.lastPing
  return p
    ? [`Kept warm at ${fmtClock(p.at)}, reuses ${fmtTokens(p.read)}. Next ${next}.`, `Warmed ${fmtClock(p.at)}, next ${next}.`, `Next ping ${next}.`]
    : [
        `Kept warm: next message reuses ${context ? fmtTokens(context.used) : 'the cache'}. Ping at ${next}.`,
        `Kept warm: next ping ${next}.`,
        `Next ping ${next}.`,
      ]
}

/** The fewest words for a terminal line too narrow for any wording above. */
export function tinyNotice(cache: CacheView, context: ContextCacheContext | null): string {
  if (cache.state === 'cooling') return `Cooling: ${fmtSpan(cache.remainingMs)} left.`
  if (cache.state === 'warm' && context?.autoCompactAt != null && context.used / context.window >= 0.85) {
    return `Compact ${Math.max(0, pct(((context.autoCompactAt - context.used) / context.window) * 100))}% away.`
  }
  return `Cache ${cache.label.toLowerCase()}.`
}

/** Every layout below the widest takes the short notice wording: beside three buttons the full sentence wraps from about 620px down. */
export function isShortNotice(size: SizeClass): boolean {
  return size !== 'a'
}

// ── Layout ─────────────────────────────────────────────────────────────────

/**
 * The design's four widths, in the cells the band is laid out in (≈ 8px a
 * cell): a ≈ 900px, b ≈ 620px (columns from ~500px), c ≈ 420px (rings),
 * d ≈ 320px (rings, no legend or detail lines).
 */
export type SizeClass = 'a' | 'b' | 'c' | 'd'

export function sizeClassOf(columns: number): SizeClass {
  if (columns >= 100) return 'a'
  if (columns >= 62) return 'b'
  if (columns >= 45) return 'c'
  return 'd'
}

/** Rows the terminal card takes in each class (border included). */
export function rowsFor(size: SizeClass, hasNotice: boolean): number {
  const body = size === 'a' || size === 'b' ? 1 + 1 + 4 + (hasNotice ? 1 : 0) : size === 'c' ? 1 + 1 + 2 + (hasNotice ? 2 : 0) : 1 + 1 + (hasNotice ? 2 : 0)
  return body + 2
}

// ── The whole view ─────────────────────────────────────────────────────────

export type ViewModel = {
  size: SizeClass
  context: {
    used: number
    window: number
    usedLabel: string
    compactPct: number | null
    rightLabel: string
    segments: { group: ContextCacheGroup; tokens: number; color: string; label: string }[]
    free: number
  } | null
  limits: LimitView[]
  cache: CacheView
  notice: string
  /** The bold start of the notice (part of `notice`), or empty. */
  noticeLead: string
  /** The notice dot's colour: the cache's, or green after a Clear or Compact. */
  noticeDot: string
  showLegend: boolean
  showDetail: boolean
}

/**
 * `fitChars`, the terminal's: the cells the notice has on its line. The
 * longest wording that fits is taken, down to the tiny one, so it never cuts
 * off. Without it (the desktop), the size class picks the wording.
 */
export function buildView(
  snap: ContextCacheSnapshot,
  now: number,
  columns: number,
  maxRows: number,
  fitChars?: number,
): ViewModel {
  let size = sizeClassOf(columns)
  const cache = cacheView(snap.cache, now)
  // Fall back to a shorter layout when the band has fewer rows than it needs.
  while (size !== 'd' && rowsFor(size, true) > maxRows) {
    size = size === 'a' ? 'c' : size === 'b' ? 'c' : 'd'
  }
  const price = priceOf(snap.model, snap.cache.ttlMs)
  const isShort = isShortNotice(size)
  // Priced wordings first (long, then short), then the same without money;
  // the desktop takes the one its size class names.
  const options: { lead: string; rest: string }[] = snap.saved
    ? [price, null].flatMap(p => [false, true].map(short => savedNotice(snap.saved!, p, short)))
    : snap.warming
      ? warmNotice(snap.warming, snap.context).map(rest => ({ lead: '', rest }))
      : [price, null].flatMap(p => [false, true].map(short => ({ lead: '', rest: noticeText(cache, snap.context, snap.cache.ttlMs, short, p) })))
  if (!snap.saved && !snap.warming) options.push({ lead: '', rest: tinyNotice(cache, snap.context) })
  const chosen =
    fitChars === undefined
      ? options[isShort ? 1 : 0]!
      : (options.find(o => (o.lead + o.rest).length <= fitChars) ?? options[options.length - 1]!)
  const saved = snap.saved ? chosen : null
  const notice = chosen.lead + chosen.rest

  const ctx = snap.context
  const context = ctx
    ? (() => {
        const compactPct = ctx.autoCompactAt === null ? null : pct((ctx.autoCompactAt / ctx.window) * 100)
        const wide = size === 'a' || size === 'b'
        const rightLabel =
          compactPct === null
            ? `${pct((ctx.used / ctx.window) * 100)}%`
            : wide
              ? `Compact at ${compactPct}%`
              : `${compactPct}%`
        return {
          used: ctx.used,
          window: ctx.window,
          usedLabel: `${fmtTokens(ctx.used)} / ${fmtTokens(ctx.window)} (${pct((ctx.used / ctx.window) * 100)}%)`,
          compactPct,
          rightLabel,
          segments: GROUPS.map(g => ({
            group: g,
            tokens: ctx.parts[g],
            color: GROUP_COLORS[g],
            label: GROUP_LABELS[g],
          })),
          free: Math.max(0, ctx.window - ctx.used),
        }
      })()
    : null

  const byKind = (k: ContextCacheLimitKind) => snap.limits.find(l => l.kind === k)
  const limits = (['session', 'weekly', 'fable'] as const).map(k => limitView(k, byKind(k), now, snap.pulse?.[k]))

  return {
    size,
    context,
    limits,
    cache,
    notice,
    noticeLead: saved ? saved.lead : '',
    noticeDot: saved ? TOKENS.saved : cache.color,
    showLegend: size !== 'd',
    showDetail: size === 'a' || size === 'b',
  }
}

// ── /cache-mini ────────────────────────────────────────────────────────────

/**
 * The panel as one line: context %, the cache and what the next message costs
 * ("Context 45% · Cache warm, 59m left · Next message ≈$0.09"). The longest
 * wording that fits `columns` less the dot is taken.
 */
export function miniLine(snap: ContextCacheSnapshot, now: number, columns: number): string {
  const cache = cacheView(snap.cache, now)
  const ctx = snap.context
  const price = priceOf(snap.model, snap.cache.ttlMs)
  const live = cache.state === 'warm' || cache.state === 'cooling'
  const left = live
    ? snap.cache.ttlMs < 10 * 60_000
      ? fmtSpan(cache.remainingMs, true)
      : `${Math.max(1, Math.round(cache.remainingMs / 60_000))}m`
    : ''
  const usd = ctx && price ? fmtUsd(ctx.used * (live ? price.read : price.write)) : ''
  const p = ctx ? `${pct((ctx.used / ctx.window) * 100)}%` : ''
  const join = (...parts: string[]) => parts.filter(Boolean).join(' · ')
  const options = [
    join(p && `Context ${p}`, `Cache ${cache.label.toLowerCase()}${left ? `, ${left} left` : ''}`, usd && `Next message ${usd}`),
    join(p, `${cache.label}${left ? ` ${left}` : ''}`, usd),
    join(p, `${cache.label}${left ? ` ${left}` : ''}`),
    cache.label,
  ]
  const room = columns - 2
  const fit = options.find(o => o.length <= room)
  return fit ?? options[options.length - 1]!.slice(0, Math.max(0, room))
}

// ── Colour helpers ─────────────────────────────────────────────────────────

function hexToRgb(hex: string): [number, number, number] {
  const h = hex.replace('#', '')
  return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)]
}

function rgbToHex([r, g, b]: [number, number, number]): string {
  return `#${[r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('')}`
}

/** Mixes `a` toward `b` by `t` (0 → a, 1 → b). */
export function mix(a: string, b: string, t: number): string {
  const x = hexToRgb(a)
  const y = hexToRgb(b)
  return rgbToHex([x[0] + (y[0] - x[0]) * t, x[1] + (y[1] - x[1]) * t, x[2] + (y[2] - x[2]) * t])
}

/** The temperature gradient: blue → amber (50%) → orange. */
export function tempColorAt(x: number): string {
  const t = Math.max(0, Math.min(1, x))
  return t < 0.5 ? mix(CACHE_COLORS.cold, CACHE_COLORS.cooling, t / 0.5) : mix(CACHE_COLORS.cooling, CACHE_COLORS.warm, (t - 0.5) / 0.5)
}

